<template>

<section class="agent-stream"> <div class="stream-header"> <div> <span class="stream-title">Agent Activity</span> <span class="stream-count">{{ output.length }} events</span> </div> <div class="stream-actions"> <button v-if="collapsibleCount" class="stream-clear" type="button" @click="toggleAll" > {{ allExpanded ? "Collapse all" : "Expand all" }} </button> <button v-if="output.length" class="stream-clear" type="button" @click="$emit('clear')" > Clear </button> </div> </div> <div ref="consoleElement" class="stream-body"> <div v-if="!output.length" class="stream-empty"> <div class="empty-orb">✦</div> <strong>{{ session ? "Waiting for agent activity" : "Start a new session" }}</strong> <span> {{ session ? "Agent events, runtime actions and results will appear here." : "Describe your task below and run the agent." }} </span> </div> <article v-for="(item, index) in output" :key="`${item.timestamp || 0}-${index}`" class="event-card" :class="[`event-${item.type}`, { 'event-condensed': isCollapsible(item) }]" > <div class="event-marker"> <span>{{ getIcon(item) }}</span> </div> <div class="event-content"> <div class="event-meta"> <span class="event-type">{{ getLabel(item) }}</span> <span v-if="getActionTag(item)" class="event-tag"> {{ getActionTag(item) }} </span> <span v-if="isCollapsible(item)" class="event-lines"> {{ getLineCount(item) }} lines </span> <time v-if="item.timestamp"> {{ formatTime(item.timestamp) }} </time> </div> <template v-if="isCollapsible(item)"> <div v-if="!isExpanded(index)" class="event-preview"> {{ getPreview(item) }} </div> <div v-else class="event-full"> <pre v-if="isStructured(item.content)">{{ item.content }}</pre> <div v-else class="event-text">{{ item.content }}</div> </div> <button class="event-toggle" type="button" @click="toggle(index)" > <span class="event-toggle-icon">{{ isExpanded(index) ? "▴" : "▾" }}</span> {{ isExpanded(index) ? "Show less" : "Show more" }} </button> </template> <template v-else> <pre v-if="isStructured(item.content)">{{ item.content }}</pre> <div v-else class="event-text">{{ item.content }}</div> </template> </div> </article> </div> </section> </template><script setup> import { computed, nextTick, ref, watch } from "vue"; const props = defineProps({ output: { type: Array, default: () => [] }, session: { type: Object, default: null }, }); defineEmits(["clear"]); const consoleElement = ref(null); const expanded = ref(new Set()); // 折叠阈值：内容较长或行数较多时默认折叠 const PREVIEW_MAX_CHARS = 160; const PREVIEW_MAX_LINES = 3; watch( () => props.output.length, async () => { await nextTick(); if (!consoleElement.value) { return; } consoleElement.value.scrollTop = consoleElement.value.scrollHeight; } ); function getLabel(item) { const type = item.type; if (type === "system") return "System"; if (type === "stderr" || type === "error") return "Error"; if (type === "stdout") return getActionTag(item) === "answer" ? "Answer" : "Agent"; return "Event"; } function getIcon(item) { if (item.type === "system") return "◆"; if (item.type === "stderr" || item.type === "error") return "!"; const tag = getActionTag(item); if (tag === "answer") return "★"; if (tag === "read") return "R"; if (tag === "write") return "W"; if (tag === "exec") return "$"; return "›"; } /** * 从 agent 事件里取出 XML Action 名（read / write / exec / answer / done）。 * session 记录里 record.event 保存了原始 agent 事件。 */ function getActionTag(item) { const event = item.event; if (!event) { return ""; } if (event.type === "runtime.result" && event.action) { return event.action; } if (event.type === "answer") { return "answer"; } if (event.type === "action.parsed" && event.action) { return event.action; } return ""; } function contentText(item) { if (typeof item.content !== "string") { return ""; } return item.content; } function getLineCount(item) { const text = contentText(item); if (!text) { return 0; } return text.split("\n").length; } /** * 是否可折叠：内容较长、行数较多，或本身就是结构化 JSON。 * answer / read / write / exec 这类大块输出默认折叠，保持界面清爽。 */ function isCollapsible(item) { const text = contentText(item); if (!text) { return false; } const tag = getActionTag(item); // answer 通常很长，始终允许折叠 if (tag === "answer") { return true; } if (text.length > PREVIEW_MAX_CHARS) { return true; } if (getLineCount(item) > PREVIEW_MAX_LINES) { return true; } return false; } /** * 折叠时展示的摘要：取前几行 / 前若干字符，最多 3 行。 */ function getPreview(item) { const text = contentText(item); if (!text) { return ""; } const lines = text.split("\n"); const head = lines.slice(0, PREVIEW_MAX_LINES).join("\n"); const truncatedByLine = lines.length > PREVIEW_MAX_LINES; const truncatedByChar = head.length > PREVIEW_MAX_CHARS; const shown = truncatedByChar ? head.slice(0, PREVIEW_MAX_CHARS) : head; if (truncatedByLine || truncatedByChar) { return shown.replace(/\s+$/, "") + " …"; } return shown; } function isStructured(content) { if (typeof content !== "string") { return true; } return content.includes("\n{") || content.startsWith("{"); } function isExpanded(index) { return expanded.value.has(index); } function toggle(index) { const next = new Set(expanded.value); if (next.has(index)) { next.delete(index); } else { next.add(index); } expanded.value = next; } const collapsibleIndexes = computed(() => { const list = []; props.output.forEach((item, index) => { if (isCollapsible(item)) { list.push(index); } }); return list; }); const collapsibleCount = computed(() => collapsibleIndexes.value.length); const allExpanded = computed(() => { if (!collapsibleIndexes.value.length) { return false; } return collapsibleIndexes.value.every((index) => expanded.value.has(index)); }); function toggleAll() { if (allExpanded.value) { expanded.value = new Set(); return; } expanded.value = new Set(collapsibleIndexes.value); } function formatTime(timestamp) { return new Date(timestamp).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit", }); } </script>

